begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table focus_scope(course uuid,assessment uuid,rubric uuid,next_rubric uuid,source jsonb,draft jsonb,approved jsonb,submission uuid);grant select,insert,update on focus_scope to cuevo_api;
insert into focus_scope(course,assessment)values('99660000-0000-4000-8000-000000000001','99670000-0000-4000-8000-000000000001');
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001',(select course from focus_scope),'30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Criterion review course','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,status,assignment_state,intended_model)values('10000000-0000-4000-8000-000000000001',(select assessment from focus_scope),(select course from focus_scope),'20000000-0000-4000-8000-000000000004','Review alternatives','Compare and justify the chosen approach.',10,'DRAFT','CLOSED','rubric');
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update focus_scope set rubric=internal.create_rubric(course,'Compare alternatives','school-1','[{"key":"comparison","title":"Comparison","levels":[{"key":"shown","label":"Shown","description":"Compare the supplied alternatives."}]}]'),next_rubric=internal.create_rubric(course,'Changed criterion','school-2','[{"key":"justification","title":"Justification","levels":[{"key":"shown","label":"Shown","description":"Justify a chosen alternative."}]}]');
select internal.prepare_assessment((select assessment from focus_scope),'Review alternatives','Compare and justify the chosen approach.',null,10,'61000000-0000-4000-8000-000000000001',(select rubric from focus_scope),1)is not null;
update focus_scope set source=internal.read_thinking_focus('criterion',assessment,'comparison');
select is((select source->>'targetTitle'from focus_scope),'Comparison','criterion customer title uses authorized rubric context');
select is((select source->'source'->>'rubricVersion'from focus_scope),(select rubric::text||':school-1'from focus_scope),'criterion source pins immutable rubric identity/version');
update focus_scope set draft=internal.thinking_focus_command('draft','criterion',assessment,'comparison',jsonb_build_object('expectedRevision',0,'expectedSourceVersion',source->>'sourceVersion','focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','ANALYZE','additionalProcesses',jsonb_build_array('EVALUATE')),'rationale','Compare alternatives and justify a choice.'),'scope-criterion-draft',repeat('a',64),'focus-scope');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000005',true);
select throws_ok($$select internal.thinking_focus_command('draft','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','CREATE','additionalProcesses','[]'::jsonb),'rationale','Unassigned teacher edit'),'scope-wrong-course',repeat('b',64),'focus-scope')$$,'42501',null,'another teacher cannot author another managed course');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select throws_ok($$select internal.thinking_focus_command('review','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',9,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'decision','APPROVE','reason','Stale version','confirmReview',true),'scope-stale-review',repeat('b',64),'focus-scope')$$,'22023',null,'stale classification revision denied');
update focus_scope set approved=internal.thinking_focus_command('review','criterion',assessment,'comparison',jsonb_build_object('expectedRevision',1,'expectedSourceVersion',source->>'sourceVersion','decision','APPROVE','reason','Reviewed exact rubric criterion and task.','confirmReview',true),'scope-criterion-review',repeat('c',64),'focus-scope');
reset role;update app.entitlements set enabled=false where school_id='10000000-0000-4000-8000-000000000001'and code='curriculum';
set local role cuevo_api;
select throws_ok($$select internal.thinking_focus_command('review','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'decision','APPROVE','reason','Reviewed exact rubric criterion and task.','confirmReview',true),'scope-criterion-review',repeat('c',64),'focus-scope')$$,'42501',null,'original review key cannot bypass revoked curriculum entitlement');
reset role;update app.entitlements set enabled=true where school_id='10000000-0000-4000-8000-000000000001'and code='curriculum';update app.memberships set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000002';
set local role cuevo_api;
select throws_ok($$select internal.read_thinking_focus('criterion',(select assessment from focus_scope),'comparison')$$,'42501',null,'revoked reviewer membership cannot read classification source');
reset role;update app.memberships set status='active'where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000002';
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.configure_assessment_rubric((select assessment from focus_scope),(select next_rubric from focus_scope),3)is not null;
select is(internal.read_thinking_focus('criterion',(select assessment from focus_scope),'comparison')->>'status','SOURCE_CHANGED','removed criterion preserves source-changed review history');
select is(internal.read_thinking_focus('criterion',(select assessment from focus_scope),'comparison')->>'canAuthor','false','removed criterion does not advertise author permission');
select throws_ok($$select internal.thinking_focus_command('draft','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',2,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','ANALYZE','additionalProcesses','[]'::jsonb),'rationale','Removed criterion'),'scope-removed-criterion',repeat('d',64),'focus-scope')$$,'42501',null,'removed criterion cannot receive new classification');
select is(internal.read_thinking_focus_history('criterion',(select assessment from focus_scope),'comparison',25,null)->'items'->0->'source'->>'criterionTitle','Comparison','criterion history preserves original immutable human title');
select internal.prepare_assessment((select assessment from focus_scope),'Review alternatives','Compare and justify the chosen approach.',null,10,'61000000-0000-4000-8000-000000000001',(select rubric from focus_scope),2)is not null;
select is(internal.read_thinking_focus('criterion',(select assessment from focus_scope),'comparison')->>'status','SOURCE_CHANGED','restored key with new policy/preparation does not restore stale approval');
select throws_ok($$select internal.thinking_focus_command('review','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'decision','APPROVE','reason','Reviewed exact rubric criterion and task.','confirmReview',true),'scope-criterion-review',repeat('c',64),'focus-scope')$$,'42501',null,'teacher cannot use coordinator original key');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select throws_ok($$select internal.thinking_focus_command('review','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',1,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'decision','APPROVE','reason','Reviewed exact rubric criterion and task.','confirmReview',true),'scope-criterion-review',repeat('c',64),'focus-scope')$$,'22023',null,'original review key cannot bypass changed preparation/policy/rubric source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update focus_scope set source=internal.read_thinking_focus('criterion',assessment,'comparison');
select internal.thinking_focus_command('draft','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',2,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'focus',jsonb_build_object('taxonomyVersion','revised-bloom-2001-cuevo-v1','primaryProcess','ANALYZE','additionalProcesses','[]'::jsonb),'rationale','Reviewed restored task criterion.'),'scope-current-criterion-draft',repeat('e',64),'focus-scope')is not null;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000002',true);
select internal.thinking_focus_command('review','criterion',(select assessment from focus_scope),'comparison',jsonb_build_object('expectedRevision',3,'expectedSourceVersion',(select source->>'sourceVersion'from focus_scope),'decision','APPROVE','reason','Reviewed restored current source.','confirmReview',true),'scope-current-criterion-review',repeat('f',64),'focus-scope')is not null;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.publish_prepared_assessment((select assessment from focus_scope),3,5,1)is not null;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
update focus_scope set submission=internal.create_learning_submission(assessment,'Comparison and justification.');
select is(internal.read_thinking_focus_snapshot('submission',(select submission from focus_scope))->'items'->0->'target'->>'kind','CRITERION','submission captures exact approved criterion demand');
select is(internal.read_thinking_focus_snapshot('submission',(select submission from focus_scope))->'items'->0->'source'->>'criterionTitle','Comparison','criterion snapshot retains authorized human label');
reset role;update app.enrollments set status='revoked'where school_id='10000000-0000-4000-8000-000000000001'and student_actor_id='20000000-0000-4000-8000-000000000012';set local role cuevo_api;
select throws_ok($$select internal.read_thinking_focus_snapshot('submission',(select submission from focus_scope))$$,'42501',null,'snapshot rechecks exact current enrollment after revocation');
select*from finish();rollback;
